  var seed = SR.get(KEYS);
  var b = '<div class="logo serif">HOLMGARD <b>AND BEYOND</b></div>' +
    '<div class="sub">0.4 \u2014 The Road to Miklagard</div>' +
    '<div class="card"><p class="hint center">Prototype: the lake crossing, the landing at Aldeigjuborg, the river road to Holmgard, and now the southern water-road: Smaleskja, K\u00e6nugar\u00f0r, the rapids and the Greek sea to Miklagard \u2014 and the east road beyond: the Volga venture to Bulgar, Itil and the narrated caravan to Baghdad.</p>';
