        '<button onclick="hub3(\'tfreight\')" ' + (freeH < 1 ? 'disabled' : '') + '>Take a merchant\u2019s freight bale <span class="mut">' + (freeH < 1 ? '\u2014 hold full' : '\u2014 free \u00b7 1 unit \u00b7 pays 2 dirhams at Bulgar') + '</span></button>'
